UPDATE public.profiles SET about_text = 'Depuis notre création en 2003, forte de ses 23 ans d''expérience, TOP GRAD s''est imposée comme un acteur de référence sur le marché marocain de l''équipement pour la cuisine professionnelle, la restauration et les métiers de bouche.

